 var dialog=document.createElement('dialog');dialog.setAttribute('aria-label','Atualizar cadastros do projeto a partir dos compartilhados');dialog.style.cssText='width:min(760px,94vw);max-height:88vh;overflow:auto;border:1px solid var(--border2);border-radius:12px;padding:24px;background:var(--bg,#181818);color:var(--text,#fff);margin:auto';
 dialog.innerHTML='<h2>Atualizar a partir dos cadastros compartilhados</h2><p><strong>'+orcEsc(p.nome)+' → '+orcEsc(String(t.codigo).padStart(2,'0')+' — '+t.nome)+'</strong></p><p>Esta ação substitui todos os cadastros próprios deste tipo pelos padrões compartilhados atuais, incluindo campos vazios e alterações feitas diretamente no projeto. Os demais tipos, as identidades dos participantes e as propostas emitidas serão preservados.</p><ul>'+ORC_CADASTROS_VISIVEIS.map(function(k){return '<li>'+orcEsc(ORC_CADASTROS[k])+'</li>';}).join('')+'</ul><p>As configurações auxiliares vinculadas também serão sincronizadas. A atualização será concluída por inteiro ou não será aplicada.</p><p role="status" id="orc-sync-status"></p><button class="btn btn-primary" id="orc-sync-confirm">Atualizar todos os cadastros deste tipo</button> <button class="btn btn-ghost" id="orc-sync-cancel">Cancelar</button>';
 document.body.appendChild(dialog);var salvar=dialog.querySelector('#orc-sync-confirm'),cancel=dialog.querySelector('#orc-sync-cancel'),busy=false;
